import os
from openpyxl import load_workbook, Workbook
from openpyxl.chart import ScatterChart, Reference, Series
from openpyxl.chart.marker import Marker


class ExcelReport(object):
    """Class contains keywords handling operations on Excel file"""

    def __init__(self, excel_file_path):
        """
        Initialize excel class.

        :param excel_file_path: full path to existing Excel file or path where new Excel is created.
        """
        self._file_path = excel_file_path
        self._filename = os.path.basename(excel_file_path)
        self._file_dir = os.path.dirname(excel_file_path)

    @property
    def file_path(self):
        """
        Get path to excel file.

        :return: path
        """
        return self._file_path

    @property
    def file_exists(self):
        """
        Get information if excel file was created under file_path.

        :return: True if file exists, False otherwise.
        """
        try:
            load_workbook(filename=self.file_path)
            return True
        except OSError:
            return False

    @property
    def worksheets(self):
        """
        Get list of current sheets' names.

        :return: list of names
        """
        workbook = load_workbook(filename=self.file_path)
        return workbook.sheetnames

    def get_max_row(self, sheetname=None):
        """
        Get number of the last full row in worksheet (does not include graphs).

        :param sheetname: name of sheet; if None active sheet's rows are checked
        :return: row number
        """
        workbook = load_workbook(filename=self.file_path)
        if sheetname is None:
            worksheet = workbook.active
        else:
            worksheet = workbook[sheetname]
        return worksheet.max_row

    def get_worksheet(self, name=None, workbook=None):
        """
        Get existing sheet object with given name. If name is None return active sheet.

        :param name: name of existing sheet
        :param workbook: Workbook object containing sheet;
               if None workbook is loaded from path but it makes it impossible to save changes to given worksheet
        :return: Worksheet object
        """
        if workbook is None:
            workbook = load_workbook(filename=self.file_path)
        if name is None:
            worksheet = workbook.active
        else:
            worksheet = workbook[name]
        return worksheet

    def create_new_excel_file(self, headers, data, sheetname=None):
        """
        Create new excel file filled with given data.

        :param headers: list of headers (column names); first row in excel
        :param data: list of lists: each list is a row in excel
        :param sheetname: name of the first sheet; if None default name Sheet is used
        :return: None
        """
        workbook = Workbook()
        worksheet = workbook.active
        if sheetname is not None:
            worksheet.title = sheetname
        worksheet.append(headers)
        for row in data:
            worksheet.append(row)
        workbook.save(self.file_path)

    def add_graph_to_excel(self, x_header=None, y_header=None, title=None, label=None, anchor=None, sheetname=None):
        """
        Add line graph to existing file using data it contains.

        :param x_header: header of column containing X axis data - header have to be in the first row
        :param y_header: header of column containing Y axis data - header have to be in the first row
        :param title: title of the whole graph
        :param label: title of the graph's line
        :param anchor: credentials of cell where top left corner of the graph is attached
        :param sheetname: name of sheet; if None graph is added to active sheet
        :return: None
        """
        if title is None:
            title = "{} vs {}".format(x_header, y_header)
        if label is None:
            label = "graph1"

        graph_params = {
            label: {
                "x_header": x_header,
                "y_header": y_header
            }
        }
        self.add_multi_line_graph_to_excel(graph_lines_params=graph_params, x_axis_title=x_header,
                                           y_axis_title=y_header, graph_title=title, anchor=anchor,
                                           sheetname=sheetname)

    def add_multi_line_graph_to_excel(self, graph_lines_params, x_axis_title, y_axis_title, graph_title, anchor=None,
                                      sheetname=None):
        """
        Add line graph with multiple lines to existing file using data it contains.

        :param graph_lines_params: dictionary with graphs labels as keys and graphs headers as values e.g.
                                   {
                                       "label1": {
                                           "x_header": "xheader1",
                                           "y_header": "yheader1"
                                      },
                                      "label2": {
                                           "x_header": "xheader2",
                                           "y_header": "yheader2"
                                      },
                                  }
        :param x_axis_title: title of x axis
        :param y_axis_title: title of y axis
        :param graph_title: title of the whole graph
        :param anchor: credentials of cell where top left corner of the graph is attached
        :param sheetname: name of sheet; if None graph is added to active sheet
        :return: None
        """
        workbook = load_workbook(filename=self.file_path)
        worksheet = self.get_worksheet(name=sheetname, workbook=workbook)

        headers = list(worksheet.iter_rows(values_only=True))[0]

        chart = ScatterChart()
        chart.title = graph_title

        chart.x_axis.title = x_axis_title
        chart.y_axis.title = y_axis_title

        chart.x_axis.tickLblPos = "high"
        chart.y_axis.tickLblPos = "high"

        for graph_label in graph_lines_params.keys():
            x_header = graph_lines_params[graph_label]["x_header"]
            y_header = graph_lines_params[graph_label]["y_header"]
            x_header_index = headers.index(x_header) + 1
            y_header_index = headers.index(y_header) + 1
            xvalues = Reference(worksheet=worksheet, min_col=x_header_index, min_row=2, max_row=worksheet.max_row)
            values = Reference(worksheet=worksheet, min_col=y_header_index, min_row=2, max_row=worksheet.max_row)
            series = Series(values, xvalues, title_from_data=False, title=graph_label)
            series.marker = Marker('circle')
            chart.series.append(series)

        if anchor is None:
            anchor = "A{}".format(worksheet.max_row + 3)
        worksheet.add_chart(chart, anchor)
        workbook.save(self.file_path)

    def add_worksheet(self, name=None):
        """
        Add empty worksheet to existing excel file.

        :param name: worksheet name; default Sheet[1,2,3...]
        :return: None
        """
        workbook = load_workbook(filename=self.file_path)
        worksheet = workbook.create_sheet()
        if name:
            worksheet.title = name
        workbook.save(self.file_path)

    def add_data_to_worksheet(self, data, headers=None, name=None):
        """
        Add data at the end of given sheet.

        :param name: name of existing sheet; if None active sheet is used
        :param data: list of lists or tuples; each list/tuple is one row of data in excel
        :param headers: list of headers (column names); first row in excel; if None data is added from the first row
        :return: None
        """
        workbook = load_workbook(filename=self.file_path)
        worksheet = self.get_worksheet(name=name, workbook=workbook)
        if headers is not None:
            worksheet.append(headers)
        for row in data:
            worksheet.append(row)
        workbook.save(self.file_path)

    def get_column_values_by_header(self, header_name, sheetname=None, workbook=None):
        """
        Get list of values from excel column with given header.
        :param header_name: value from the first cell in column
        :param sheetname: name of sheet; default None
        :param workbook: Workbook object containing sheet;
               if None workbook is loaded from path but it makes it impossible to save changes to given worksheet
        :return: list of column values; the first value is the header
        """
        worksheet = self.get_worksheet(name=sheetname, workbook=workbook)
        try:
            rows = list(worksheet.values)
            col_idx = rows[0].index(header_name)
        except ValueError:
            raise ValueError("'{}' header not found in sheet '{}'".format(header_name, sheetname))
        return [row[col_idx] for row in worksheet.values]
